-- ----------------------------
-- Table structure for gkzh_zyxxz_student_choice
-- ----------------------------
DROP TABLE IF EXISTS `gkzh_zyxxz_student_choice`;
CREATE TABLE `gkzh_zyxxz_student_choice`  (
  `choice_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '选择ID',
  `student_id` bigint(20) NULL DEFAULT NULL COMMENT '学生ID',
  `student_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学生姓名',
  `student_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学号',
  `activity_id` bigint(20) NULL DEFAULT NULL COMMENT '活动ID',
  `common_channel` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最常用求职信息渠道',
  `trusted_channel` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最信任求职信息渠道',
  `obstacles` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取障碍（逗号分隔）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`choice_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '职业信息站-学生选择记录' ROW_FORMAT = Dynamic;

