-- ----------------------------
-- Table structure for wjdc_survey
-- ----------------------------
DROP TABLE IF EXISTS `wjdc_survey`;
CREATE TABLE `wjdc_survey`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问卷标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '问卷说明',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '0=已发布, 1=未发布',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '问卷主表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wjdc_survey
-- ----------------------------

-- ----------------------------
-- Table structure for wjdc_survey_answer
-- ----------------------------
DROP TABLE IF EXISTS `wjdc_survey_answer`;
CREATE TABLE `wjdc_survey_answer`  (
  `answer_id` int(11) NOT NULL AUTO_INCREMENT,
  `response_id` int(11) NOT NULL COMMENT '答卷ID',
  `question_id` int(11) NOT NULL COMMENT '问题ID',
  `answer_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '单选/多选为选项ID用英文逗号分隔，简答为文本',
  PRIMARY KEY (`answer_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 240864 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户答题记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wjdc_survey_answer
-- ----------------------------

-- ----------------------------
-- Table structure for wjdc_survey_option
-- ----------------------------
DROP TABLE IF EXISTS `wjdc_survey_option`;
CREATE TABLE `wjdc_survey_option`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question_id` int(11) NOT NULL COMMENT '问题 ID',
  `option_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '选项内容',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '显示排序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 274 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '题目选项表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wjdc_survey_option
-- ----------------------------

-- ----------------------------
-- Table structure for wjdc_survey_question
-- ----------------------------
DROP TABLE IF EXISTS `wjdc_survey_question`;
CREATE TABLE `wjdc_survey_question`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '问题ID',
  `survey_id` int(11) NOT NULL COMMENT '问卷ID',
  `question_title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问题标题',
  `question_type` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '问题类型（1=单选题, 2=多选题, 3=填空题）',
  `required` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否必填（0=否, 1=是）',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '显示排序',
  `score_range` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分值范围（如：1-9）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_survey_id`(`survey_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 129 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '问卷问题表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wjdc_survey_question
-- ----------------------------

-- ----------------------------
-- Table structure for wjdc_survey_response
-- ----------------------------
DROP TABLE IF EXISTS `wjdc_survey_response`;
CREATE TABLE `wjdc_survey_response`  (
  `response_id` int(11) NOT NULL AUTO_INCREMENT,
  `survey_id` int(11) NOT NULL COMMENT '问卷ID',
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `submitted_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  PRIMARY KEY (`response_id`) USING BTREE,
  UNIQUE INDEX `uk_user_survey`(`survey_id`, `user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9478 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户答卷表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wjdc_survey_response
-- ----------------------------

