CREATE TABLE `xycc_career`  (
  `career_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业名称，如”工程师“',
  PRIMARY KEY (`career_id`) USING BTREE,
  UNIQUE INDEX `uk_title`(`title`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 351 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '职业方向表' ROW_FORMAT = DYNAMIC;

