-- Records of xycc_career
-- ----------------------------

-- ----------------------------
-- Table structure for xycc_pattern
-- ----------------------------
DROP TABLE IF EXISTS `xycc_pattern`;
CREATE TABLE `xycc_pattern`  (
  `pattern_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `row_index` tinyint(2) NULL DEFAULT NULL COMMENT '行号，从0开始',
  `row_code` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行编号（R、I)',
  `col_index` tinyint(2) NULL DEFAULT NULL COMMENT '列好，从0开始',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图案名称，如“激光测距仪”',
  `img_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图案图片地址',
  PRIMARY KEY (`pattern_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '心愿橱窗' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of xycc_pattern
-- ----------------------------

-- ----------------------------
-- Table structure for xycc_pattern_combo
-- ----------------------------
DROP TABLE IF EXISTS `xycc_pattern_combo`;
CREATE TABLE `xycc_pattern_combo`  (
  `pattern_combo_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '组合编码，如“RIA”',
  PRIMARY KEY (`pattern_combo_id`) USING BTREE,
  UNIQUE INDEX `uk_pattern_code`(`pattern_combo_id`, `code`) USING BTREE,
  INDEX `idx_pattern_combo_code`(`code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 127 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '编码组合表' ROW_FORMAT = DYNAMIC;

