-- Table structure for xycc_pattern_combo_career
-- ----------------------------
DROP TABLE IF EXISTS `xycc_pattern_combo_career`;
CREATE TABLE `xycc_pattern_combo_career`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `combo_id` int(11) NULL DEFAULT NULL COMMENT '编码组合表ID',
  `career_id` int(11) NULL DEFAULT NULL COMMENT '职业方向表ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_combo_career_combo_id`(`combo_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 372 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '编码组合 - 职业方向 关联表' ROW_FORMAT = DYNAMIC;

