  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `combo_id` int(11) NULL DEFAULT NULL COMMENT '编码组合表ID',
  `env_id` int(11) NULL DEFAULT NULL COMMENT '工作环境偏好表ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_combo_env_combo_id`(`combo_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 371 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '编码组合 - 工作环境偏好 关联表' ROW_FORMAT = DYNAMIC;

