-- ----------------------------
-- Table structure for xycc_user_selection
-- ----------------------------
DROP TABLE IF EXISTS `xycc_user_selection`;
CREATE TABLE `xycc_user_selection`  (
  `user_selection_id` bigint(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint(11) NULL DEFAULT NULL COMMENT '用户ID',
  `pattern_ids` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逗号分隔',
  `pattern_combo_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '如”RIA“',
  `created_at` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '选择时间',
  PRIMARY KEY (`user_selection_id`) USING BTREE,
  INDEX `idx_user_selection_user_id`(`user_id`) USING BTREE,
  INDEX `idx_user_selection_pattern_code`(`pattern_combo_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11243 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户选择记录表' ROW_FORMAT = DYNAMIC;

