  PRIMARY KEY (`work_env_id`) USING BTREE,
  UNIQUE INDEX `uk_title`(`title`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 294 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工作环境偏好表' ROW_FORMAT = DYNAMIC;

